<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
  <meta name="robots" content="noindex,nofollow"><title>Sun Son Solar Portal</title>
  <link rel="stylesheet" href="<?= esc(base_url('assets/portal.css'), 'attr') ?>">
</head>
<body class="portal-app" data-role="<?= esc($user['role'], 'attr') ?>" data-api="<?= esc(site_url('api'), 'attr') ?>">
  <a class="portal-skip" href="#main">Skip to dashboard</a>
  <header class="portal-top"><a class="brand" href="<?= esc(site_url(), 'attr') ?>"><span aria-hidden="true">☀</span>SUN SON SOLAR</a><div class="top-actions"><span><?= esc(trim($user['first_name'] . ' ' . $user['last_name'])) ?> · <?= esc(ucwords($user['role'])) ?></span><button id="signout" type="button">Sign out</button></div></header>
  <div class="portal-layout"><aside class="portal-side"><p class="eyebrow">YOUR WORKSPACE</p><nav id="portal-nav" aria-label="Dashboard sections"></nav></aside><main class="portal-main" id="main"><p>Loading your workspace…</p></main></div>
  <footer class="portal-footer">Sun Son Solar Inc. · <a href="<?= esc(site_url('privacy'), 'attr') ?>">Privacy</a> · <a href="<?= esc(site_url('terms'), 'attr') ?>">Terms</a></footer>
  <script>
    const api = document.body.dataset.api;
    const role = document.body.dataset.role;
    let csrf = '';
    let state = {};
    const esc = (value) => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
    const fmt = value => value ? new Date(String(value).replace(' ','T')+'Z').toLocaleString() : 'Not scheduled';
    const localInput = value => { if (!value) return ''; const date=new Date(String(value).replace(' ','T')+'Z'); date.setMinutes(date.getMinutes()-date.getTimezoneOffset()); return date.toISOString().slice(0,16); };
    async function request(path, data) {
      const response = await fetch(api + '/portal/' + path, {method:data ? 'POST' : 'GET', credentials:'same-origin', cache:'no-store', headers:data ? {'Content-Type':'application/json','X-CSRF-Token':csrf} : {}, body:data ? JSON.stringify(data) : undefined});
      const result = await response.json();
      if (!response.ok) throw new Error(result.error || 'The request could not be completed.');
      return result;
    }
    function formData(form) { return Object.fromEntries(new FormData(form)); }
    function section(id,title,content) { return `<section class="portal-section" id="${id}"><h2>${title}</h2>${content}</section>`; }
    function card(title,content) { return `<article class="portal-card"><h3>${title}</h3>${content}</article>`; }
    function statusBox() { return '<p class="portal-status" role="status" aria-live="polite"></p>'; }
    function nav(items) { document.querySelector('#portal-nav').innerHTML=items.map(([id,label],i)=>`<a href="#${id}" ${i===0?'aria-current="page"':''}>${label}</a>`).join(''); }
    function bookingRows(rows,manager=false,tech=false) {
      if (!rows.length) return '<p>No service bookings yet.</p>';
      if (tech) return `<div class="portal-list">${rows.map(b=>`<article class="portal-item"><strong>#${b.id} · ${esc(b.service_name)}</strong><span>${esc(b.customer_first)} ${esc(b.customer_last)} · ${esc(b.service_address)}</span><br><small>${esc(b.status)} · ${esc(fmt(b.scheduled_start))}</small><div class="portal-form"><button class="p-button checkin" data-id="${b.id}">Check in with GPS</button><form class="report-job"><input type="hidden" name="booking_id" value="${b.id}"><label>On-site issue or equipment note<textarea name="report" required maxlength="10000"></textarea></label><button class="p-button alt">Send report</button></form></div></article>`).join('')}</div>`;
      if (manager) return `<div class="portal-table-wrap"><table class="portal-table"><thead><tr><th>Customer / service</th><th>Requested</th><th>Assign technician</th><th>Schedule</th><th>Status</th><th>Save</th></tr></thead><tbody>${rows.map(b=>`<tr><td><strong>#${b.id} · ${esc(b.customer_first)} ${esc(b.customer_last)}</strong><br>${esc(b.service_name)} · ${esc(b.service_address)}<br><small>${esc(b.customer_notes||'')}</small></td><td>${esc(fmt(b.requested_at))}</td><td><select class="assign-tech" data-id="${b.id}"><option value="">Unassigned</option>${(state.technicians||[]).map(t=>`<option value="${t.id}" ${String(t.id)===String(b.technician_id)?'selected':''}>${esc(t.first_name)} ${esc(t.last_name)}</option>`).join('')}</select></td><td><input class="schedule-start" data-id="${b.id}" type="datetime-local" value="${localInput(b.scheduled_start)}"><input class="schedule-end" data-id="${b.id}" type="datetime-local" value="${localInput(b.scheduled_end)}"></td><td><select class="booking-status" data-id="${b.id}">${['requested','approved','declined','scheduled','in_progress','completed','cancelled'].map(s=>`<option ${s===b.status?'selected':''}>${s}</option>`).join('')}</select></td><td><button class="p-button save-booking" data-id="${b.id}">Save</button></td></tr>`).join('')}</tbody></table></div>`;
      return `<div class="portal-table-wrap"><table class="portal-table"><thead><tr><th>Service</th><th>Preferred / scheduled</th><th>Technician</th><th>Status</th><th>Details</th><th>Manage</th></tr></thead><tbody>${rows.map(b=>`<tr><td>${esc(b.service_name)}</td><td>${esc(fmt(b.scheduled_start||b.requested_at))}</td><td>${esc([b.technician_first,b.technician_last].filter(Boolean).join(' ')||'To be assigned')}</td><td>${esc(b.status)}</td><td>${esc(b.service_address)}<br>${esc(b.customer_notes||'')}</td><td>${['requested','approved','scheduled'].includes(b.status)?`<button class="p-button warn cancel-booking" data-id="${b.id}">Cancel</button>`:'—'}</td></tr>`).join('')}</tbody></table></div>`;
    }
    function render() {
      const customer=role==='customer', tech=role==='technician', admin=role==='admin', hr=role==='hr', dispatcher=role==='dispatcher', manager=admin||dispatcher;
      const items=customer?[['schedule','Schedule'],['notifications','Notifications'],['profile','Profile'],['history','History'],['support','Support'],['stories','Customer stories']]:tech?[['jobs','Assigned jobs'],['announcements','Announcements']]:manager?[['calendar','Schedule calendar'],['support','Support tickets'],...(admin?[['reports','Reports & analytics'],['alerts','Customer alerts'],['settings','System settings'],['announcements','Announcements'],['stories','Customer stories']]:[])]:hr?[['users','User management'],['announcements','Announcements']]:[['announcements','Announcements']];
      if (admin) items.unshift(['users','User management']);
      nav(items);
      const title=customer?'Customer dashboard':tech?'Technician field portal':admin?'Admin control center':dispatcher?'Dispatcher control center':hr?'HR control center':'Employee workspace';
      let html=`<h1>${title}</h1><p class="portal-lead">Welcome, ${esc(state.user.first_name)}. Your Sun Son Solar workspace is ready.</p>`;
      if(customer) {
        const options=(state.categories||[]).map(c=>`<option value="${c.id}">${esc(c.name)}${c.base_price!==null?' · ₱'+esc(c.base_price):''}</option>`).join('');
        html+=section('schedule','Schedule and manage service',`<div class="portal-grid">${card('Request a service',`<form id="booking-form" class="portal-form"><label>Service<select name="category_id" required>${options}</select></label><label>Preferred date and time<input type="datetime-local" name="requested_at"></label><label>Service address<input name="service_address" value="${esc(state.user.address||'')}" required maxlength="300"></label><label>Project details<textarea name="customer_notes" maxlength="3000"></textarea></label>${statusBox()}<button class="p-button">Request service</button></form>`)}${card('Your bookings',bookingRows(state.bookings||[]))}</div>`);
        html+=section('notifications','Notifications',card('Recent updates',(state.notifications||[]).length?`<div class="portal-list">${state.notifications.map(n=>`<div class="portal-item"><strong>${esc(n.title)}</strong><span>${esc(n.message)}</span><br><small>${esc(fmt(n.created_at))}</small></div>`).join('')}</div>`:'<p>No updates right now.</p>'));
        html+=section('profile','Profile and preferences',`<div class="portal-grid">${card('Personal information',`<form id="profile-form" class="portal-form"><div class="portal-grid"><label>First name<input name="first_name" required value="${esc(state.user.first_name)}"></label><label>Middle name<input name="middle_name" value="${esc(state.user.middle_name||'')}"></label><label>Last name<input name="last_name" required value="${esc(state.user.last_name)}"></label><label>Birthdate<input type="date" name="birthday" value="${esc(state.user.birthday||'')}"></label><label>Gender<select name="gender">${['','Woman','Man','Non-binary','Self-described','Prefer not to say'].map(x=>`<option ${x===(state.user.gender||'')?'selected':''}>${esc(x)}</option>`).join('')}</select></label><label>Email<input type="email" name="email" required value="${esc(state.user.email)}"></label><label>Phone<input name="phone" required value="${esc(state.user.phone||'')}"></label><label>Address<input name="address" required value="${esc(state.user.address||'')}"></label></div><label class="inline"><input type="checkbox" name="promotions" ${Number(state.preferences.promotions)?'checked':''}> Promotions</label><label class="inline"><input type="checkbox" name="schedule_updates" ${Number(state.preferences.schedule_updates)?'checked':''}> Schedule updates</label>${statusBox()}<button class="p-button">Save profile</button></form>`)}${card('Change password',`<form id="password-form" class="portal-form"><label>Current password<input type="password" name="current_password" required autocomplete="current-password"></label><label>New password<input type="password" name="new_password" required minlength="12" autocomplete="new-password"></label>${statusBox()}<button class="p-button alt">Change password</button></form>`)}</div>`);
        html+=section('history','Service and payment history',`<div class="portal-grid">${card('Completed services',bookingRows((state.bookings||[]).filter(b=>b.status==='completed')))}${card('Payments and receipts',state.payments?.length?`<div class="portal-table-wrap"><table class="portal-table"><thead><tr><th>Service</th><th>Amount</th><th>Status</th><th>Reference / date</th></tr></thead><tbody>${state.payments.map(p=>`<tr><td>${esc(p.service_name)}</td><td>₱${esc(p.amount)}</td><td>${esc(p.status)}</td><td>${esc(p.reference||'—')}<br>${esc(fmt(p.paid_at||p.created_at))}</td></tr>`).join('')}</tbody></table></div>`:'<p>No payments have been recorded yet.</p>')}</div>`);
        html+=section('support','Support and help',`<div class="portal-grid">${card('Contact support',`<form id="ticket-form" class="portal-form"><label>Subject<input name="subject" required maxlength="160"></label><label>How can we help?<textarea name="message" required maxlength="5000"></textarea></label>${statusBox()}<button class="p-button">Submit support ticket</button></form>`)}${card('Your support requests',state.tickets?.length?`<div class="portal-list">${state.tickets.map(t=>`<div class="portal-item"><strong>${esc(t.subject)} · ${esc(t.status)}</strong><span>${esc(t.message)}</span>${t.staff_reply?`<p><b>Sun Son Solar:</b> ${esc(t.staff_reply)}</p>`:''}</div>`).join('')}</div>`:'<p>No support tickets yet.</p>')}</div>`);
        html+=section('stories','Customer stories',card('Share your experience',state.testimonial?`<p>Your story has been received and is waiting for team review.</p><blockquote>${esc(state.testimonial.quote_text)}</blockquote><small>Publication: ${Number(state.testimonial.is_published)?'Published':'Pending review'}</small>`:`<form id="testimonial-form" class="portal-form"><label>Your story<textarea name="quote_text" required maxlength="1200"></textarea></label><label>Name to display<input name="display_name" required maxlength="120"></label><label class="inline"><input type="checkbox" name="consent_to_publish" required> I give permission for Sun Son Solar to publish this story with the display name above.</label>${statusBox()}<button class="p-button">Submit for review</button></form>`));
      } else if(tech) {
        html+=section('jobs','Assigned jobs',card('Today and upcoming',bookingRows(state.bookings||[],false,true)));
        html+=section('announcements','Safety and HR announcements',card('Team feed',listItems(state.announcements,'body')));
      } else {
        if(admin||hr) html+=section('users','User management',userManagement());
        if(manager) html+=section('calendar','Calendar and schedule overview',card('All service bookings',bookingRows(state.bookings||[],true)));
        if(admin) html+=section('reports','Reports and analytics',analytics()+paymentEntry());
        if(manager) html+=section('support','Support tickets',supportManagement());
        if(admin) html+=section('alerts','Customer notifications',card('Send customer alert',`<form id="notify-form" class="portal-form"><label>Customer (blank sends to all active customers)<select name="user_id"><option value="">All customers</option>${(state.users||[]).filter(u=>u.role==='customer'&&Number(u.is_active)).map(u=>`<option value="${u.id}">${esc(u.first_name)} ${esc(u.last_name)}</option>`).join('')}</select></label><label>Title<input name="title" required maxlength="160"></label><label>Message<textarea name="message" required maxlength="1000"></textarea></label>${statusBox()}<button class="p-button">Send alert</button></form>`));
        if(admin) html+=section('settings','System settings',settingsView());
        if(admin||hr) html+=section('announcements','Announcements and HR notices',`<div class="portal-grid">${card('Publish announcement',`<form id="announcement-form" class="portal-form"><label>Title<input name="title" required maxlength="160"></label><label>Message<textarea name="body" required maxlength="10000"></textarea></label><label>Audience<select name="audience"><option value="all_staff">All staff</option><option value="technicians">Technicians</option><option value="dispatchers">Dispatchers</option><option value="managers">Managers</option></select></label>${statusBox()}<button class="p-button">Publish</button></form>`)}${card('Team feed',listItems(state.announcements,'body'))}</div>`);
        if(admin) html+=section('stories','Customer stories',testimonialModeration());
        if(!admin&&!hr&&!manager) html+=section('announcements','Announcements',card('Team feed',listItems(state.announcements,'body')));
      }
      document.querySelector('#main').innerHTML=html;
      bindForms();
    }
    function listItems(items,textKey){return items?.length?`<div class="portal-list">${items.map(i=>`<div class="portal-item"><strong>${esc(i.title)}</strong><span>${esc(i[textKey]||i.message)}</span><br><small>${esc(fmt(i.created_at))}</small></div>`).join('')}</div>`:'<p>No announcements yet.</p>';}
    function userManagement(){const depts=state.departments||[];return `<div class="portal-grid">${card('Add employee',`<form id="employee-form" class="portal-form" autocomplete="off"><div class="portal-grid"><label>First name<input name="first_name" required></label><label>Middle name<input name="middle_name"></label><label>Last name<input name="last_name" required></label><label>Birthdate<input name="birthday" type="date" required></label><label>Gender<select name="gender" required><option>Woman</option><option>Man</option><option>Non-binary</option><option>Self-described</option><option>Prefer not to say</option></select></label><label>Email<input name="email" type="email" required></label><label>Phone<input name="phone" required></label><label>Address<input name="address" required></label><label>Username<input name="username" autocomplete="off" required minlength="3"></label><label>Temporary password<input name="password" type="password" autocomplete="new-password" required minlength="12"></label><label>Department<select name="department">${depts.map(d=>`<option>${esc(d)}</option>`).join('')}</select></label><label>Role<select name="role">${(role==='admin'?['employee','technician','dispatcher','hr','admin']:['employee','technician','dispatcher']).map(r=>`<option value="${r}">${r}</option>`).join('')}</select></label></div>${statusBox()}<button class="p-button">Create employee account</button></form>`)}${card('Customer and employee accounts',`<div class="portal-table-wrap"><table class="portal-table"><thead><tr><th>Name / username</th><th>Type</th><th>Department</th><th>Contact</th><th>State</th><th>Action</th></tr></thead><tbody>${(state.users||[]).map(u=>`<tr><td>${esc(u.first_name)} ${esc(u.last_name)}<br><small>${esc(u.username)} · ${esc(u.birthday||'')}</small></td><td>${esc(u.role)}</td><td>${esc(u.department||'—')}</td><td>${esc(u.email)}<br><small>${esc(u.phone||'')} · ${esc(u.address||'')}</small></td><td>${Number(u.is_active)?'Active':'Inactive'}</td><td><button class="p-button alt account-edit" data-id="${u.id}">Edit</button> <button class="p-button ${Number(u.is_active)?'warn':'alt'} account-state" data-id="${u.id}" data-active="${Number(u.is_active)?0:1}">${Number(u.is_active)?'Deactivate':'Activate'}</button></td></tr>`).join('')}</tbody></table></div>` )}</div>`;}
    function analytics(){const a=state.analytics||{};const max=Math.max(1,...(a.revenue_by_month||[]).map(x=>Number(x.total)));const serviceMax=Math.max(1,...(a.services||[]).map(x=>Number(x.total)));const customerMax=Math.max(1,...(a.customer_activity||[]).map(x=>Number(x.total)));return `<div class="portal-stat-grid"><div class="portal-stat"><span>Recorded revenue</span><strong>₱${esc(Number(a.revenue||0).toLocaleString())}</strong></div><div class="portal-stat"><span>Service bookings</span><strong>${esc(a.bookings||0)}</strong></div><div class="portal-stat"><span>Customers</span><strong>${esc(a.customers||0)}</strong></div><div class="portal-stat"><span>Active customers</span><strong>${esc(a.active_customers||0)}</strong></div></div><div class="portal-grid portal-chart">${card('Revenue by month',`<div class="bar-list">${(a.revenue_by_month||[]).map(x=>`<div class="bar-row"><span>${esc(x.month)}</span><div class="bar-track"><progress max="100" value="${Math.max(2,Number(x.total)/max*100)}"></progress></div><strong>₱${esc(Number(x.total).toLocaleString())}</strong></div>`).join('')||'<p>No paid revenue recorded.</p>'}</div>`)}${card('Service usage',`<div class="bar-list">${(a.services||[]).map(x=>`<div class="bar-row"><span>${esc(x.name)}</span><div class="bar-track"><progress max="100" value="${Math.max(3,Number(x.total)/serviceMax*100)}"></progress></div><strong>${esc(x.total)}</strong></div>`).join('')||'<p>No service activity recorded.</p>'}</div>`)}${card('Customer activity',`<div class="bar-list">${(a.customer_activity||[]).map(x=>`<div class="bar-row"><span>${esc(x.month)}</span><div class="bar-track"><progress max="100" value="${Math.max(2,Number(x.total)/customerMax*100)}"></progress></div><strong>${esc(x.total)}</strong></div>`).join('')||'<p>No new customer activity recorded.</p>'}</div>`)}${card('Technician reports',listItems(state.reports,'report'))}</div>`;}
    function supportManagement(){return card('Customer support queue',state.tickets?.length?`<div class="portal-list">${state.tickets.map(t=>`<article class="portal-item"><strong>#${t.id} · ${esc(t.subject)} · ${esc(t.status)}</strong><span>${esc(t.message)}</span><form class="ticket-reply portal-form"><input type="hidden" name="id" value="${t.id}"><label>Reply<textarea name="reply">${esc(t.staff_reply||'')}</textarea></label><label>Status<select name="status">${['open','in_progress','resolved'].map(x=>`<option ${x===t.status?'selected':''}>${x}</option>`).join('')}</select></label>${statusBox()}<button class="p-button alt">Save reply</button></form></article>`).join('')}</div>`:'<p>No support tickets in the queue.</p>');}
    function paymentEntry(){return card('Record a payment or receipt',`<form id="payment-form" class="portal-form"><label>Booking<select name="booking_id" required>${(state.bookings||[]).map(b=>`<option value="${b.id}">#${b.id} · ${esc(b.customer_first)} ${esc(b.customer_last)} · ${esc(b.service_name)}</option>`).join('')}</select></label><label>Amount in PHP<input name="amount" type="number" min="0.01" step="0.01" required></label><label>Status<select name="status"><option>paid</option><option>pending</option><option>refunded</option></select></label><label>Reference<input name="reference" maxlength="80"></label>${statusBox()}<button class="p-button">Save payment record</button></form>`);}
    function testimonialModeration(){return card('Review consented customer stories',state.testimonials?.length?`<div class="portal-list">${state.testimonials.map(t=>`<article class="portal-item"><strong>${esc(t.display_name)} · ${Number(t.is_published)?'Published':'Pending'}</strong><blockquote>${esc(t.quote_text)}</blockquote><button class="p-button ${Number(t.is_published)?'warn':'alt'} testimonial-state" data-id="${t.id}" data-publish="${Number(t.is_published)?0:1}">${Number(t.is_published)?'Unpublish':'Publish'}</button></article>`).join('')}</div>`:'<p>No customer stories submitted yet.</p>');}
    function settingsView(){return `<div class="portal-grid">${card('Booking availability',`<form id="availability-form" class="portal-form"><label class="inline"><input name="enabled" type="checkbox" ${state.settings?.booking_enabled==='1'?'checked':''}> Accept online service requests</label>${statusBox()}<button class="p-button">Save availability</button></form>`)}${card('Service categories and pricing',`<form id="category-form" class="portal-form"><label>Service name<input name="name" required maxlength="100"></label><label>Description<textarea name="description" maxlength="500"></textarea></label><label>Price in PHP (blank if quoted)<input name="base_price" type="number" min="0" step="0.01"></label><label>Duration in minutes<input name="duration_minutes" type="number" min="1" max="1440" value="60"></label><label class="inline"><input name="is_active" type="checkbox" checked> Available to customers</label>${statusBox()}<button class="p-button">Add service</button></form><div class="portal-list">${(state.all_categories||[]).map(c=>`<div class="portal-item"><strong>${esc(c.name)} · ${c.base_price===null?'Quote required':'₱'+esc(c.base_price)}</strong><span>${esc(c.description)} · ${c.duration_minutes} min · ${Number(c.is_active)?'Available':'Hidden'}</span> <button class="p-button alt edit-category" data-id="${c.id}">Edit</button></div>`).join('')}</div>`)}</div>`;}
    async function postForm(form,path,transform=x=>x){const status=form.querySelector('.portal-status');const button=form.querySelector('button[type="submit"],button:not([type])');if(button)button.disabled=true;if(status)status.textContent='Saving…';try{await request(path,transform(formData(form)));if(status)status.textContent='Saved.';await load();}catch(error){if(status)status.textContent=error.message;}finally{if(button)button.disabled=false;}}
    function bindForms(){
      document.querySelector('#booking-form')?.addEventListener('submit',e=>{e.preventDefault();postForm(e.currentTarget,'booking')});
      document.querySelector('#profile-form')?.addEventListener('submit',e=>{e.preventDefault();const d=formData(e.currentTarget);d.promotions=e.currentTarget.elements.promotions.checked;d.schedule_updates=e.currentTarget.elements.schedule_updates.checked;postForm(e.currentTarget,'profile',()=>d)});
      document.querySelector('#password-form')?.addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget;const status=form.querySelector('.portal-status');try{await request('password',formData(form));status.textContent='Password changed. Redirecting to sign in…';location.assign(<?= json_encode(site_url('login'), JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT) ?>)}catch(error){status.textContent=error.message}});
      document.querySelector('#ticket-form')?.addEventListener('submit',e=>{e.preventDefault();postForm(e.currentTarget,'ticket')});
      document.querySelector('#testimonial-form')?.addEventListener('submit',e=>{e.preventDefault();const d=formData(e.currentTarget);d.consent_to_publish=e.currentTarget.elements.consent_to_publish.checked;postForm(e.currentTarget,'testimonial',()=>d)});
      document.querySelector('#payment-form')?.addEventListener('submit',e=>{e.preventDefault();postForm(e.currentTarget,'payment')});
      document.querySelector('#employee-form')?.addEventListener('submit',e=>{e.preventDefault();postForm(e.currentTarget,'employee',d=>({...d,action:'create'}))});
      document.querySelector('#announcement-form')?.addEventListener('submit',e=>{e.preventDefault();postForm(e.currentTarget,'announcement')});
      document.querySelector('#notify-form')?.addEventListener('submit',e=>{e.preventDefault();postForm(e.currentTarget,'notify')});
      document.querySelector('#availability-form')?.addEventListener('submit',e=>{e.preventDefault();postForm(e.currentTarget,'settings',d=>({action:'availability',enabled:e.currentTarget.elements.enabled.checked}))});
      document.querySelector('#category-form')?.addEventListener('submit',e=>{e.preventDefault();postForm(e.currentTarget,'settings',d=>({...d,action:'category',is_active:e.currentTarget.elements.is_active.checked}))});
      document.querySelectorAll('.save-booking').forEach(button=>button.addEventListener('click',async()=>{const id=button.dataset.id;try{await request('booking/update',{id,status:document.querySelector(`.booking-status[data-id="${id}"]`).value,technician_id:document.querySelector(`.assign-tech[data-id="${id}"]`).value,scheduled_start:document.querySelector(`.schedule-start[data-id="${id}"]`).value,scheduled_end:document.querySelector(`.schedule-end[data-id="${id}"]`).value});await load()}catch(error){alert(error.message)}}));
      document.querySelectorAll('.account-state').forEach(button=>button.addEventListener('click',async()=>{try{await request('employee',{action:Number(button.dataset.active)?'activate':'deactivate',id:button.dataset.id});await load()}catch(error){alert(error.message)}}));
      document.querySelectorAll('.account-edit').forEach(button=>button.addEventListener('click',async()=>{const u=(state.users||[]).find(x=>String(x.id)===button.dataset.id);if(!u)return;const first_name=prompt('First name',u.first_name);if(first_name===null)return;const middle_name=prompt('Middle name',u.middle_name||'');if(middle_name===null)return;const last_name=prompt('Last name',u.last_name);if(last_name===null)return;const birthday=prompt('Birthdate (YYYY-MM-DD)',u.birthday||'');if(birthday===null)return;const gender=prompt('Gender: Woman, Man, Non-binary, Self-described, Prefer not to say',u.gender||'Prefer not to say');if(gender===null)return;const email=prompt('Email',u.email);if(email===null)return;const phone=prompt('Phone',u.phone||'');if(phone===null)return;const address=prompt('Address',u.address||'');if(address===null)return;const payload={action:'edit',id:u.id,first_name,middle_name,last_name,email,phone,address,birthday,gender};if(u.role!=='customer'){payload.department=prompt('Department',u.department||'IT');if(payload.department===null)return;if(role==='admin')payload.role=prompt('Role (employee, technician, dispatcher, hr, admin)',u.role)||u.role;}try{await request('employee',payload);await load()}catch(error){alert(error.message)}}));
      document.querySelectorAll('.cancel-booking').forEach(button=>button.addEventListener('click',async()=>{if(!confirm('Cancel this service request?'))return;try{await request('booking/cancel',{id:button.dataset.id});await load()}catch(error){alert(error.message)}}));
      document.querySelectorAll('.report-job').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();postForm(form,'report')}));
      document.querySelectorAll('.ticket-reply').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();postForm(form,'ticket/reply')}));
      document.querySelectorAll('.edit-category').forEach(button=>button.addEventListener('click',async()=>{const c=(state.all_categories||[]).find(x=>String(x.id)===button.dataset.id);if(!c)return;const name=prompt('Service name',c.name);if(name===null)return;const description=prompt('Description',c.description);if(description===null)return;const base_price=prompt('Base price in PHP (leave blank for quote)',c.base_price??'');if(base_price===null)return;const duration_minutes=prompt('Duration in minutes',c.duration_minutes);if(duration_minutes===null)return;const is_active=confirm('Keep this service available to customers?');try{await request('settings',{action:'category',id:c.id,name,description,base_price,duration_minutes,is_active});await load()}catch(error){alert(error.message)}}));
      document.querySelectorAll('.testimonial-state').forEach(button=>button.addEventListener('click',async()=>{try{await request('testimonial',{id:button.dataset.id,publish:Number(button.dataset.publish)});await load()}catch(error){alert(error.message)}}));
      document.querySelectorAll('.checkin').forEach(button=>button.addEventListener('click',()=>{if(!navigator.geolocation){alert('GPS is not available in this browser.');return;}button.disabled=true;navigator.geolocation.getCurrentPosition(async pos=>{try{await request('checkin',{booking_id:button.dataset.id,latitude:pos.coords.latitude,longitude:pos.coords.longitude});button.textContent='Checked in';}catch(error){alert(error.message);button.disabled=false}},()=>{alert('Allow location access to record your job-site check-in.');button.disabled=false},{enableHighAccuracy:true,timeout:15000,maximumAge:0})}));
    }
    async function load(){try{const data=await request('data');state=data;state.technicians=data.technicians||(data.users||[]).filter(u=>u.role==='technician'&&Number(u.is_active));render()}catch(error){document.querySelector('#main').innerHTML=`<h1>Portal unavailable</h1><p>${esc(error.message)}</p><p>Ask an administrator to apply <code>database/stakeholder_portal.sql</code> and refresh.</p>`}}
    document.querySelector('#signout').addEventListener('click',async()=>{try{const session=await fetch(api+'/session',{credentials:'same-origin'}).then(r=>r.json());await fetch(api+'/logout',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF-Token':session.csrf},body:'{}'});location.assign(<?= json_encode(site_url('login'), JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT) ?>)}catch{location.assign(<?= json_encode(site_url('login'), JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT) ?>)}});
    (async()=>{try{const session=await fetch(api+'/session',{credentials:'same-origin',cache:'no-store'}).then(r=>r.json());csrf=session.csrf;await load()}catch{location.assign(<?= json_encode(site_url('login'), JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT) ?>)}})();
  </script>
</body>
</html>

